window.QUESTION_BANK = (window.QUESTION_BANK || []).concat([
  { id: "signs-01", topic: "signs", difficulty: "easy", sign: "shape-octagon", question: "What does a sign with this shape mean?", choices: ["Yield the right-of-way to cross traffic", "Road work or maintenance ahead", "Come to a full stop", "School crossing ahead"], answerIndex: 2, explanation: "In North Carolina the eight-sided (octagon) shape is the stop sign; the law requires a full stop, and you may move again only when the way is clear.", question_pt: "O que significa uma placa com este formato?", choices_pt: ["Dar a preferência ao tráfego transversal", "Obras ou manutenção na pista à frente", "Parar completamente", "Travessia escolar à frente"], explanation_pt: "Na Carolina do Norte, o formato de oito lados (octógono) é a placa de PARE; a lei exige parada completa, e você só pode seguir quando o caminho estiver livre.", question_es: "¿Qué significa una señal con esta forma?", choices_es: ["Ceder el paso al tránsito que cruza", "Obras o mantenimiento en la vía más adelante", "Detenerse por completo", "Cruce escolar más adelante"], explanation_es: "En Carolina del Norte, la forma de ocho lados (octágono) es la señal de alto; la ley exige detenerse por completo y avanzar solo cuando el camino esté despejado." },
  { id: "signs-02", topic: "signs", difficulty: "easy", sign: "shape-triangle", question: "What does a sign with this shape (point facing down) require you to do?", choices: ["Slow down and yield the right-of-way, stopping if traffic requires it", "Always come to a full stop, even if no one is coming", "Keep your speed; cross traffic must yield to you", "Move into the left lane immediately"], answerIndex: 0, explanation: "A triangle with the point at the bottom is the yield sign: slow down and yield the right-of-way; whether you must stop depends on traffic on the intersecting street.", question_pt: "O que uma placa com este formato (ponta para baixo) exige que você faça?", choices_pt: ["Reduzir a velocidade e dar a preferência, parando se o tráfego exigir", "Sempre parar completamente, mesmo sem ninguém vindo", "Manter a velocidade; o tráfego transversal é que deve dar a preferência a você", "Mudar imediatamente para a faixa da esquerda"], explanation_pt: "O triângulo com a ponta para baixo é a placa de DÊ A PREFERÊNCIA: reduza a velocidade e dê a preferência; a necessidade de parar depende do tráfego na via transversal.", question_es: "¿Qué le exige hacer una señal con esta forma (punta hacia abajo)?", choices_es: ["Reducir la velocidad y ceder el paso, deteniéndose si el tránsito lo requiere", "Detenerse siempre por completo, aunque no venga nadie", "Mantener la velocidad; el tránsito que cruza debe cederle el paso a usted", "Cambiarse de inmediato al carril izquierdo"], explanation_es: "El triángulo con la punta hacia abajo es la señal de ceda el paso: reduzca la velocidad y ceda el paso; si debe detenerse depende del tránsito en la calle que cruza." },
  { id: "signs-03", topic: "signs", difficulty: "easy", sign: "shape-diamond-yellow", question: "What type of sign has this shape and color?", choices: ["A regulatory sign you must obey, such as a speed limit", "A warning sign about a condition or hazard ahead", "A guide sign showing directions and distances", "A route marker for a state highway"], answerIndex: 1, explanation: "Yellow diamond-shaped signs (normally black on yellow) are caution or warning signs; drive with extra care when you see one.", question_pt: "Que tipo de placa tem este formato e esta cor?", choices_pt: ["Uma placa de regulamentação que você deve obedecer, como limite de velocidade", "Uma placa de advertência sobre uma condição ou perigo à frente", "Uma placa indicativa com direções e distâncias", "Um marcador de rota de rodovia estadual"], explanation_pt: "Placas amarelas em forma de losango (normalmente pretas sobre amarelo) são placas de cautela ou advertência; dirija com cuidado redobrado ao vê-las.", question_es: "¿Qué tipo de señal tiene esta forma y este color?", choices_es: ["Una señal normativa que debe obedecer, como un límite de velocidad", "Una señal de advertencia sobre una condición o peligro más adelante", "Una señal de guía con direcciones y distancias", "Un marcador de ruta de una vía estatal"], explanation_es: "Las señales amarillas tipo diamante (normalmente negro sobre amarillo) son de precaución o advertencia; conduzca con especial cuidado al verlas." },
  { id: "signs-04", topic: "signs", difficulty: "easy", sign: "shape-diamond-orange", question: "A sign with this shape and color warns you about what?", choices: ["A school zone ahead", "A railroad crossing ahead", "A hospital or other service nearby", "Construction or maintenance work on or near the road"], answerIndex: 3, explanation: "In North Carolina, orange diamond-shaped signs with black messages warn of construction or maintenance areas (work zones).", question_pt: "Uma placa com este formato e esta cor alerta sobre o quê?", choices_pt: ["Uma zona escolar à frente", "Uma passagem de nível (ferrovia) à frente", "Um hospital ou outro serviço próximo", "Obras de construção ou manutenção na pista ou perto dela"], explanation_pt: "Na Carolina do Norte, placas laranja em forma de losango com mensagens pretas alertam sobre áreas de construção ou manutenção (zonas de obras).", question_es: "¿Sobre qué le advierte una señal con esta forma y este color?", choices_es: ["Una zona escolar más adelante", "Un cruce ferroviario más adelante", "Un hospital u otro servicio cercano", "Trabajos de construcción o mantenimiento en la vía o cerca de ella"], explanation_es: "En Carolina del Norte, las señales tipo diamante color naranja con mensajes negros advierten sobre áreas de construcción o mantenimiento (zonas de obras)." },
  { id: "signs-05", topic: "signs", difficulty: "easy", sign: "shape-pentagon", question: "What does a five-sided sign like this one warn you about?", choices: ["A school zone or school crossing", "A no-passing zone", "A railroad crossing", "A sharp curve"], answerIndex: 0, explanation: "The five-sided (pentagon) sign warns of a school zone or school crossing, where you should be especially watchful for children.", question_pt: "Sobre o que uma placa de cinco lados como esta alerta?", choices_pt: ["Uma zona escolar ou travessia de escolares", "Uma zona proibida de ultrapassagem", "Uma passagem de nível (ferrovia)", "Uma curva acentuada"], explanation_pt: "A placa de cinco lados (pentágono) alerta sobre zona escolar ou travessia de escolares, onde você deve ficar especialmente atento às crianças.", question_es: "¿Sobre qué le advierte una señal de cinco lados como esta?", choices_es: ["Una zona escolar o un cruce escolar", "Una zona de prohibido rebasar", "Un cruce ferroviario", "Una curva cerrada"], explanation_es: "La señal de cinco lados (pentágono) advierte de una zona escolar o un cruce escolar, donde debe tener especial cuidado con los niños." },
  { id: "signs-06", topic: "signs", difficulty: "easy", sign: "shape-circle", question: "A round yellow sign of this shape gives advance warning of what?", choices: ["A traffic circle (roundabout) ahead", "A stop sign hidden behind a curve", "A railroad crossing ahead", "A hospital nearby"], answerIndex: 2, explanation: "The circular yellow sign (with a black X and the letters RR) gives advance warning of a railroad crossing.", question_pt: "Uma placa amarela redonda com este formato avisa antecipadamente sobre o quê?", choices_pt: ["Uma rotatória à frente", "Uma placa de PARE escondida atrás de uma curva", "Uma passagem de nível (ferrovia) à frente", "Um hospital próximo"], explanation_pt: "A placa amarela circular (com um X preto e as letras RR) avisa antecipadamente sobre uma passagem de nível ferroviária.", question_es: "¿De qué le advierte con anticipación una señal amarilla redonda con esta forma?", choices_es: ["Una glorieta (rotonda) más adelante", "Una señal de alto oculta detrás de una curva", "Un cruce ferroviario más adelante", "Un hospital cercano"], explanation_es: "La señal amarilla circular (con una cruz negra y las letras RR) advierte con anticipación de un cruce ferroviario." },
  { id: "signs-07", topic: "signs", difficulty: "easy", sign: "shape-crossbuck", question: "Where is a sign with this X shape located?", choices: ["About a mile before a school", "At the entrance to a work zone", "At the start of a no-passing zone", "At the railroad crossing itself"], answerIndex: 3, explanation: "The X-shaped crossbuck is mounted at the railroad crossing itself; a smaller sign below it shows whether there is more than one track.", question_pt: "Onde fica uma placa com este formato de X?", choices_pt: ["Cerca de uma milha antes de uma escola", "Na entrada de uma zona de obras", "No início de uma zona proibida de ultrapassagem", "Na própria passagem de nível (cruzamento com a ferrovia)"], explanation_pt: "A placa em forma de X (cruz de Santo André) fica na própria passagem de nível; uma placa menor abaixo dela indica se há mais de um trilho.", question_es: "¿Dónde se ubica una señal con esta forma de X?", choices_es: ["Aproximadamente una milla antes de una escuela", "En la entrada de una zona de obras", "Al comienzo de una zona de prohibido rebasar", "En el propio cruce ferroviario"], explanation_es: "La señal en forma de X (cruceta) se coloca en el propio cruce ferroviario; un letrero más pequeño debajo indica si hay más de una vía." },
  { id: "signs-08", topic: "signs", difficulty: "medium", sign: "shape-pennant", question: "On which side of the road is a sign of this shape posted, and what does it mark?", choices: ["Right side; the end of a work zone", "Left side; the beginning of a no-passing zone", "Right side; a school crossing", "Left side; a lane that is about to end"], answerIndex: 1, explanation: "The yellow pennant is placed on the left side of the road and points to the beginning of a no-passing zone (solid yellow line in your lane).", question_pt: "Em que lado da via fica uma placa com este formato, e o que ela indica?", choices_pt: ["Lado direito; o fim de uma zona de obras", "Lado esquerdo; o início de uma zona proibida de ultrapassagem", "Lado direito; uma travessia escolar", "Lado esquerdo; uma faixa que está para acabar"], explanation_pt: "A placa amarela em forma de flâmula fica no lado esquerdo da via e aponta para o início de uma zona proibida de ultrapassagem (linha amarela contínua na sua faixa).", question_es: "¿En qué lado de la vía se coloca una señal con esta forma y qué indica?", choices_es: ["Lado derecho; el final de una zona de obras", "Lado izquierdo; el comienzo de una zona de prohibido rebasar", "Lado derecho; un cruce escolar", "Lado izquierdo; un carril que está por terminar"], explanation_es: "El banderín amarillo se ubica en el lado izquierdo de la vía y señala el comienzo de la zona de prohibido rebasar (línea amarilla continua en su carril)." },
  { id: "signs-09", topic: "signs", difficulty: "easy", sign: "shape-rect-white", question: "Signs of this shape and color, usually with black lettering, are mostly used for what?", choices: ["Rules such as speed limits and turn restrictions", "Warnings about construction areas", "Directions to cities and distances", "Nearby hospitals and telephones"], answerIndex: 0, explanation: "Rectangular and square signs, normally black and white or red and white, are regulatory signs that show speed limits and other rules you must obey.", question_pt: "Placas com este formato e cor, geralmente com letras pretas, são usadas principalmente para quê?", choices_pt: ["Regras como limites de velocidade e restrições de conversão", "Advertências sobre áreas de obras", "Direções para cidades e distâncias", "Hospitais e telefones próximos"], explanation_pt: "Placas retangulares e quadradas, normalmente pretas e brancas ou vermelhas e brancas, são de regulamentação e mostram limites de velocidade e outras regras que você deve obedecer.", question_es: "¿Para qué se usan principalmente las señales de esta forma y color, normalmente con letras negras?", choices_es: ["Normas como límites de velocidad y restricciones de giro", "Advertencias sobre áreas de construcción", "Direcciones a ciudades y distancias", "Hospitales y teléfonos cercanos"], explanation_es: "Las señales rectangulares y cuadradas, normalmente blancas y negras o rojas y blancas, son normativas y muestran límites de velocidad y otras regulaciones que debe obedecer." },
  { id: "signs-10", topic: "signs", difficulty: "easy", sign: "shape-rect-green", question: "What information do signs of this shape and color give you?", choices: ["Warnings about slippery pavement", "Rules you must obey, like no U-turns", "Directions and distances", "Work zone speeding penalties"], answerIndex: 2, explanation: "Rectangular green signs are guide signs; they provide directions and distances, and a mileage and directional sign can help you if you are lost.", question_pt: "Que informação placas com este formato e cor fornecem?", choices_pt: ["Advertências sobre pista escorregadia", "Regras que você deve obedecer, como proibido retorno", "Direções e distâncias", "Multas por excesso de velocidade em zonas de obras"], explanation_pt: "Placas verdes retangulares são placas indicativas (de orientação); elas fornecem direções e distâncias e podem ajudar se você estiver perdido.", question_es: "¿Qué información le dan las señales de esta forma y color?", choices_es: ["Advertencias sobre pavimento resbaladizo", "Normas que debe obedecer, como no girar en U", "Direcciones y distancias", "Multas por exceso de velocidad en zonas de obras"], explanation_es: "Las señales verdes rectangulares son señales de guía; proporcionan direcciones y distancias, y una señal de millaje y dirección puede ayudarle si se pierde." },
  { id: "signs-11", topic: "signs", difficulty: "easy", sign: "shape-rect-blue", question: "Which kind of information is shown on signs of this color?", choices: ["The beginning of a no-passing zone", "School crossing locations", "Work zone speed limits", "Nearby services such as a hospital, Highway Patrol station or telephone"], answerIndex: 3, explanation: "In North Carolina, signs pointing to a nearby hospital, Highway Patrol station or telephone are blue and white.", question_pt: "Que tipo de informação aparece em placas desta cor?", choices_pt: ["O início de uma zona proibida de ultrapassagem", "Locais de travessia escolar", "Limites de velocidade em zonas de obras", "Serviços próximos, como hospital, posto da Highway Patrol ou telefone"], explanation_pt: "Na Carolina do Norte, as placas que indicam hospital, posto da Highway Patrol (polícia rodoviária) ou telefone próximos são azuis e brancas.", question_es: "¿Qué tipo de información aparece en las señales de este color?", choices_es: ["El comienzo de una zona de prohibido rebasar", "Ubicación de cruces escolares", "Límites de velocidad en zonas de obras", "Servicios cercanos, como un hospital, una estación de la Patrulla de Caminos o un teléfono"], explanation_es: "En Carolina del Norte, las señales que indican un hospital, una estación de la Patrulla de Caminos o un teléfono cercanos son azules y blancas." },
  { id: "signs-12", topic: "signs", difficulty: "medium", sign: "shape-rect-brown", question: "A rectangular sign of this color belongs to which group of signs?", choices: ["Regulatory signs that set legal limits", "Guide signs that give directions and distances", "Warning signs for construction areas", "Railroad emergency notification signs"], answerIndex: 1, explanation: "The NC handbook lists green, brown and blue as the colors of rectangular guide signs, which provide directions and distances.", question_pt: "Uma placa retangular desta cor pertence a qual grupo de placas?", choices_pt: ["Placas de regulamentação que estabelecem limites legais", "Placas indicativas que dão direções e distâncias", "Placas de advertência para áreas de obras", "Placas de notificação de emergência ferroviária"], explanation_pt: "O manual da Carolina do Norte lista verde, marrom e azul como as cores das placas indicativas retangulares, que fornecem direções e distâncias.", question_es: "¿A qué grupo de señales pertenece una señal rectangular de este color?", choices_es: ["Señales normativas que fijan límites legales", "Señales de guía que dan direcciones y distancias", "Señales de advertencia de áreas de construcción", "Señales de notificación de emergencia ferroviaria"], explanation_es: "El manual de Carolina del Norte indica que las señales de guía rectangulares pueden ser verdes, marrones o azules, y proporcionan direcciones y distancias." },
  { id: "signs-13", topic: "signs", difficulty: "medium", sign: "shape-shield", question: "A route marker with this shape identifies which kind of highway?", choices: ["An N.C. state highway", "An N.C. secondary road", "A U.S. highway or an interstate highway", "A road inside a work zone"], answerIndex: 2, explanation: "Route markers for U.S. highways are shield-shaped, and interstates are marked by a red, white and blue shield; N.C. routes use a diamond instead.", question_pt: "Um marcador de rota com este formato identifica que tipo de rodovia?", choices_pt: ["Uma rodovia estadual da Carolina do Norte (N.C.)", "Uma estrada secundária da Carolina do Norte", "Uma rodovia federal (U.S.) ou uma rodovia interestadual", "Uma estrada dentro de uma zona de obras"], explanation_pt: "Os marcadores das rodovias federais (U.S.) têm forma de escudo, e as interestaduais são marcadas com um escudo vermelho, branco e azul; as rotas estaduais N.C. usam um losango.", question_es: "¿Qué tipo de vía identifica un marcador de ruta con esta forma?", choices_es: ["Una vía estatal de Carolina del Norte (N.C.)", "Una vía secundaria de Carolina del Norte", "Una vía nacional (U.S.) o una vía interestatal", "Un camino dentro de una zona de obras"], explanation_es: "Las señales de ruta de las vías nacionales (U.S.) tienen forma de escudo, y las interestatales se marcan con un escudo rojo, blanco y azul; las rutas estatales N.C. usan un diamante." },
  { id: "signs-14", topic: "signs", difficulty: "medium", sign: "shape-diamond-white", question: "In North Carolina, a white route marker with this shape (with a number inside) identifies which kind of road?", choices: ["An N.C. state highway", "A U.S. highway", "An interstate highway", "An N.C. secondary road"], answerIndex: 0, explanation: "North Carolina route markers are diamond-shaped, while U.S. and interstate routes use shields and N.C. secondary road signs are rectangular.", question_pt: "Na Carolina do Norte, um marcador de rota branco com este formato (com um número dentro) identifica que tipo de estrada?", choices_pt: ["Uma rodovia estadual da Carolina do Norte (N.C.)", "Uma rodovia federal (U.S.)", "Uma rodovia interestadual", "Uma estrada secundária da Carolina do Norte"], explanation_pt: "Os marcadores das rotas da Carolina do Norte têm forma de losango; as rotas U.S. e interestaduais usam escudos, e as placas de estradas secundárias da N.C. são retangulares.", question_es: "En Carolina del Norte, ¿qué tipo de vía identifica un marcador de ruta blanco con esta forma (con un número adentro)?", choices_es: ["Una vía estatal de Carolina del Norte (N.C.)", "Una vía nacional (U.S.)", "Una vía interestatal", "Una vía secundaria de Carolina del Norte"], explanation_es: "Las señales de ruta de Carolina del Norte tienen forma de diamante; las rutas U.S. e interestatales usan escudos, y las de vías secundarias de N.C. son rectangulares." },
  { id: "signs-15", topic: "signs", difficulty: "medium", sign: "shape-triangle-orange", question: "You see this emblem on the back of a vehicle ahead of you. What does it tell you?", choices: ["The vehicle is carrying hazardous materials", "The driver is a beginner with a learner permit", "The vehicle is about to turn left", "The vehicle travels slowly, so be patient and prepare to slow down"], answerIndex: 3, explanation: "This orange triangle marks a slow-moving vehicle such as farm equipment; you close in on it very quickly, so approach with care and never pass it in a no-passing zone.", question_pt: "Você vê este emblema na traseira de um veículo à sua frente. O que ele indica?", choices_pt: ["O veículo transporta materiais perigosos", "O motorista é iniciante com permissão de aprendizagem", "O veículo está prestes a virar à esquerda", "O veículo anda devagar; tenha paciência e prepare-se para reduzir a velocidade"], explanation_pt: "Este triângulo laranja identifica um veículo lento, como equipamento agrícola; você se aproxima dele muito rápido, então chegue com cuidado e nunca o ultrapasse em zona proibida de ultrapassagem.", question_es: "Ve este emblema en la parte trasera de un vehículo delante de usted. ¿Qué le indica?", choices_es: ["El vehículo transporta materiales peligrosos", "El conductor es principiante con permiso de aprendizaje", "El vehículo está por girar a la izquierda", "El vehículo avanza lentamente; tenga paciencia y prepárese para reducir la velocidad"], explanation_es: "Este triángulo naranja identifica un vehículo lento, como maquinaria agrícola; usted se acerca a él muy rápido, así que aproxímese con cuidado y nunca lo rebase en una zona de prohibido rebasar." },
  { id: "signs-16", topic: "signs", difficulty: "medium", sign: "shape-octagon", question: "Which statement about signs with this shape is true in North Carolina?", choices: ["The shape is shared by stop signs and yield signs", "The shape is used only for stop signs", "The shape is used for railroad warnings", "The shape means you may roll through slowly if no traffic is coming"], answerIndex: 1, explanation: "The octagon shape is used for stop signs only, and a stop sign always requires a full stop.", question_pt: "Qual afirmação sobre placas com este formato é verdadeira na Carolina do Norte?", choices_pt: ["O formato é usado tanto para PARE quanto para DÊ A PREFERÊNCIA", "O formato é usado somente para placas de PARE", "O formato é usado para advertências de ferrovia", "O formato significa que você pode passar devagar sem parar se não houver tráfego"], explanation_pt: "O formato octogonal é usado somente para placas de PARE, e a placa de PARE sempre exige parada completa.", question_es: "¿Qué afirmación sobre las señales con esta forma es verdadera en Carolina del Norte?", choices_es: ["La forma se usa tanto para alto como para ceda el paso", "La forma se usa únicamente para señales de alto", "La forma se usa para advertencias ferroviarias", "La forma significa que puede pasar despacio sin detenerse si no viene tránsito"], explanation_es: "La forma octogonal se usa únicamente para señales de alto, y la señal de alto siempre exige detenerse por completo." },
  { id: "signs-17", topic: "signs", difficulty: "medium", sign: "shape-triangle", question: "You reach a sign of this shape, and vehicles on the cross street are so close that you would get in their way. What must you do?", choices: ["Stop and wait for that traffic to pass before going", "Speed up to get in ahead of them", "Sound your horn and proceed", "Proceed, since only a stop sign can require you to stop"], answerIndex: 0, explanation: "At a yield sign, your need to stop depends on cross traffic; to avoid interfering with that traffic, you must stop and wait for it to pass.", question_pt: "Você chega a uma placa com este formato e os veículos na via transversal estão tão perto que você atrapalharia a passagem deles. O que deve fazer?", choices_pt: ["Parar e esperar esse tráfego passar antes de seguir", "Acelerar para entrar na frente deles", "Buzinar e seguir", "Seguir, pois somente a placa de PARE pode exigir que você pare"], explanation_pt: "Na placa de DÊ A PREFERÊNCIA, a necessidade de parar depende do tráfego transversal; para não atrapalhá-lo, você deve parar e esperar que ele passe.", question_es: "Llega a una señal con esta forma y los vehículos de la calle que cruza están tan cerca que usted les estorbaría. ¿Qué debe hacer?", choices_es: ["Detenerse y esperar a que pase ese tránsito antes de avanzar", "Acelerar para pasar antes que ellos", "Tocar la bocina y avanzar", "Avanzar, ya que solo una señal de alto puede obligarlo a detenerse"], explanation_es: "En la señal de ceda el paso, la necesidad de detenerse depende del tránsito que cruza; para no interferir con él, debe detenerse y esperar a que pase." },
  { id: "signs-18", topic: "signs", difficulty: "medium", sign: "shape-diamond-orange", question: "Under North Carolina rules, signs of this color with black messages are reserved for what purpose?", choices: ["Marking school zones", "Pointing to tourist attractions", "Identifying highway work zones", "Showing interstate exits"], answerIndex: 2, explanation: "Orange signs with black letters are reserved strictly to identify work zones, both as you approach and while you travel through the zone.", question_pt: "Pelas regras da Carolina do Norte, placas desta cor com mensagens pretas são reservadas para qual finalidade?", choices_pt: ["Marcar zonas escolares", "Indicar atrações turísticas", "Identificar zonas de obras nas rodovias", "Mostrar saídas de rodovias interestaduais"], explanation_pt: "Placas laranja com letras pretas são reservadas exclusivamente para identificar zonas de obras, tanto na aproximação quanto dentro da zona.", question_es: "Según las normas de Carolina del Norte, ¿para qué se reservan las señales de este color con mensajes negros?", choices_es: ["Marcar zonas escolares", "Indicar atracciones turísticas", "Identificar zonas de obras en las vías", "Mostrar salidas de vías interestatales"], explanation_es: "Las señales naranjas con letras negras se reservan estrictamente para identificar zonas de obras, tanto al acercarse como dentro de la zona." },
  { id: "signs-19", topic: "signs", difficulty: "medium", sign: "shape-circle", question: "What should you do when you see a sign of this shape and color beside the road?", choices: ["Enter the roundabout and yield to traffic on the left", "Stop at the sign every time, then continue", "Speed up so you clear the area quickly", "Slow down, look and listen, and stop if needed to be sure you can cross safely"], answerIndex: 3, explanation: "This round yellow sign warns that a railroad crossing is ahead; slow down and stop if necessary to be sure you can safely clear the tracks.", question_pt: "O que você deve fazer ao ver uma placa com este formato e cor à beira da estrada?", choices_pt: ["Entrar na rotatória e dar a preferência ao tráfego da esquerda", "Parar junto à placa todas as vezes e depois seguir", "Acelerar para sair logo da área", "Reduzir a velocidade, olhar e escutar, e parar se necessário para ter certeza de que pode atravessar com segurança"], explanation_pt: "Esta placa amarela redonda avisa que há uma passagem de nível ferroviária à frente; reduza a velocidade e pare se necessário para ter certeza de que pode cruzar os trilhos com segurança.", question_es: "¿Qué debe hacer al ver una señal con esta forma y color junto a la vía?", choices_es: ["Entrar a la glorieta y ceder el paso al tránsito de la izquierda", "Detenerse junto a la señal todas las veces y luego seguir", "Acelerar para salir rápido de la zona", "Reducir la velocidad, mirar y escuchar, y detenerse si es necesario para asegurarse de poder cruzar de manera segura"], explanation_es: "Esta señal amarilla redonda advierte que hay un cruce ferroviario más adelante; reduzca la velocidad y deténgase si es necesario para asegurarse de poder cruzar las vías de manera segura." },
  { id: "signs-20", topic: "signs", difficulty: "hard", sign: "shape-pentagon", question: "In many areas marked by signs of this shape, what may change during certain hours of the day?", choices: ["Right turns on red become mandatory", "The speed limit is reduced", "Passing on the right becomes legal", "Headlights are no longer required"], answerIndex: 1, explanation: "Pentagon signs mark school zones and school crossings, and in many school zones the speed limit is reduced during certain school hours.", question_pt: "Em muitas áreas marcadas por placas com este formato, o que pode mudar em certos horários do dia?", choices_pt: ["Virar à direita no vermelho passa a ser obrigatório", "O limite de velocidade é reduzido", "Ultrapassar pela direita passa a ser permitido", "Os faróis deixam de ser obrigatórios"], explanation_pt: "Placas em forma de pentágono marcam zonas escolares e travessias de escolares, e em muitas zonas escolares o limite de velocidade é reduzido em certos horários escolares.", question_es: "En muchas áreas marcadas con señales de esta forma, ¿qué puede cambiar durante ciertas horas del día?", choices_es: ["Girar a la derecha con luz roja se vuelve obligatorio", "Se reduce el límite de velocidad", "Rebasar por la derecha se vuelve legal", "Las luces delanteras dejan de ser obligatorias"], explanation_es: "Las señales en forma de pentágono marcan zonas y cruces escolares, y en muchas zonas escolares el límite de velocidad se reduce durante determinados horarios escolares." },
  { id: "signs-21", topic: "signs", difficulty: "medium", sign: "stop-ahead", question: "Why is this sign placed well before an intersection?", choices: ["Because a curve or other object blocks your view of the stop sign", "Because the intersection has a flashing yellow signal", "Because the speed limit drops to 25 mph there", "Because a school is next to the intersection"], answerIndex: 0, explanation: "The STOP AHEAD warning sign is posted far ahead of a stop sign when the driver's view of the stop sign is blocked by a curve or other objects.", question_pt: "Por que esta placa é colocada bem antes de um cruzamento?", choices_pt: ["Porque uma curva ou outro objeto bloqueia a visão da placa de PARE", "Porque o cruzamento tem um sinal amarelo piscante", "Porque o limite de velocidade cai para 25 mph ali", "Porque há uma escola ao lado do cruzamento"], explanation_pt: "A placa de advertência PARE ADIANTE (STOP AHEAD) é colocada bem antes de uma placa de PARE quando a visão do motorista é bloqueada por uma curva ou outros objetos.", question_es: "¿Por qué esta señal se coloca mucho antes de una intersección?", choices_es: ["Porque una curva u otro objeto bloquea la vista de la señal de alto", "Porque la intersección tiene una luz amarilla intermitente", "Porque el límite de velocidad baja a 25 mph allí", "Porque hay una escuela junto a la intersección"], explanation_es: "La señal de advertencia PARE ADELANTE [STOP AHEAD] se coloca muy por delante de una señal de alto cuando la vista del conductor está bloqueada por una curva u otros objetos." },
  { id: "signs-22", topic: "signs", difficulty: "hard", sign: "no-passing-zone", question: "How does this sign relate to the rectangular DO NOT PASS sign?", choices: ["It replaces the DO NOT PASS sign on rural roads", "It cancels the DO NOT PASS sign, so passing is allowed again", "It emphasizes the DO NOT PASS sign rather than replacing it", "It applies only to trucks, while the DO NOT PASS sign applies to cars"], answerIndex: 2, explanation: "The yellow pennant emphasizes, rather than replaces, the regulatory DO NOT PASS sign, and it points to the beginning of the no-passing zone.", question_pt: "Qual é a relação desta placa com a placa retangular PROIBIDO ULTRAPASSAR (DO NOT PASS)?", choices_pt: ["Ela substitui a placa PROIBIDO ULTRAPASSAR nas estradas rurais", "Ela cancela a placa PROIBIDO ULTRAPASSAR, liberando a ultrapassagem", "Ela reforça a placa PROIBIDO ULTRAPASSAR, em vez de substituí-la", "Ela vale só para caminhões, enquanto a placa PROIBIDO ULTRAPASSAR vale para carros"], explanation_pt: "A flâmula amarela reforça, e não substitui, a placa de regulamentação PROIBIDO ULTRAPASSAR, e aponta para o início da zona proibida de ultrapassagem.", question_es: "¿Qué relación tiene esta señal con la señal rectangular NO REBASAR [DO NOT PASS]?", choices_es: ["La reemplaza en los caminos rurales", "La anula, de modo que se permite rebasar otra vez", "La enfatiza en lugar de reemplazarla", "Se aplica solo a camiones, mientras que NO REBASAR se aplica a autos"], explanation_es: "El banderín amarillo enfatiza, en lugar de reemplazar, la señal normativa NO REBASAR, y señala el comienzo de la zona de prohibido rebasar." },
  { id: "signs-23", topic: "signs", difficulty: "medium", sign: "crossbuck", question: "At a railroad crossing marked only by this sign (no lights or gates), what is the rule?", choices: ["Trains must stop for vehicles already waiting", "You may cross without slowing if the road is busy", "Emergency vehicles have the right-of-way over trains", "You must always yield to a train"], answerIndex: 3, explanation: "Vehicles must always yield to a train, even when the crossing has only a crossbuck and no lights or gates; trains have the right-of-way over all highway traffic.", question_pt: "Em uma passagem de nível marcada apenas por esta placa (sem luzes nem cancelas), qual é a regra?", choices_pt: ["Os trens devem parar para os veículos que já estão esperando", "Você pode cruzar sem reduzir se a via estiver movimentada", "Veículos de emergência têm preferência sobre os trens", "Você deve sempre dar a preferência ao trem"], explanation_pt: "Os veículos devem sempre dar a preferência ao trem, mesmo quando a passagem tem apenas a cruz de Santo André, sem luzes nem cancelas; o trem tem preferência sobre todo o tráfego rodoviário.", question_es: "En un cruce ferroviario marcado solo con esta señal (sin luces ni barreras), ¿cuál es la regla?", choices_es: ["Los trenes deben detenerse ante los vehículos que ya esperan", "Puede cruzar sin reducir la velocidad si la vía está congestionada", "Los vehículos de emergencia tienen derecho de paso sobre los trenes", "Siempre debe ceder el paso al tren"], explanation_es: "Los vehículos siempre deben ceder el paso al tren, incluso cuando el cruce solo tiene la cruceta, sin luces ni barreras; el tren tiene derecho de paso sobre todo el tránsito vial." },
  { id: "signs-24", topic: "signs", difficulty: "easy", sign: "do-not-stop-on-tracks", question: "What does this sign tell you?", choices: ["Stop on the tracks only if traffic ahead is stopped", "Never stop on the railroad tracks for any reason", "Stop on the tracks to look for trains", "Do not stop within 50 feet of a school bus"], answerIndex: 1, explanation: "The DO NOT STOP ON TRACKS sign reminds drivers not to stop on a railroad track for any reason.", question_pt: "O que esta placa indica?", choices_pt: ["Pare sobre os trilhos somente se o trânsito à frente estiver parado", "Nunca pare sobre os trilhos do trem, por nenhum motivo", "Pare sobre os trilhos para procurar trens", "Não pare a menos de 50 pés de um ônibus escolar"], explanation_pt: "A placa NÃO PARE SOBRE OS TRILHOS (DO NOT STOP ON TRACKS) lembra ao motorista que não deve parar sobre a linha férrea por nenhum motivo.", question_es: "¿Qué le indica esta señal?", choices_es: ["Detenerse sobre las vías solo si el tránsito de adelante está detenido", "Nunca detenerse sobre las vías del tren por ningún motivo", "Detenerse sobre las vías para buscar trenes", "No detenerse a menos de 50 pies de un autobús escolar"], explanation_es: "La señal NO PARAR EN LAS VÍAS [DO NOT STOP ON TRACKS] recuerda al conductor que no debe detenerse en la vía del ferrocarril por ningún motivo." },
  { id: "signs-25", topic: "signs", difficulty: "hard", sign: "road-work", question: "Under North Carolina law, where does a highway work zone begin and end?", choices: ["From the first orange cone to the last flagger", "Only where workers are present at that moment", "From the first sign marking the start of the work zone to the last sign marking its end", "From one mile before the first sign to one mile after the last sign"], answerIndex: 2, explanation: "A highway work zone is the area between the first sign that indicates the beginning of the work zone and the last sign that indicates its end.", question_pt: "Pela lei da Carolina do Norte, onde começa e termina uma zona de obras na rodovia?", choices_pt: ["Do primeiro cone laranja até o último sinalizador", "Apenas onde há trabalhadores naquele momento", "Da primeira placa que indica o início da zona de obras até a última placa que indica o seu fim", "De uma milha antes da primeira placa até uma milha depois da última"], explanation_pt: "A zona de obras na rodovia é a área entre a primeira placa que indica o início da zona e a última placa que indica o seu fim.", question_es: "Según la ley de Carolina del Norte, ¿dónde comienza y termina una zona de obras en la vía?", choices_es: ["Desde el primer cono naranja hasta el último abanderado", "Solo donde hay trabajadores en ese momento", "Desde la primera señal que indica el inicio de la zona de obras hasta la última señal que indica su final", "Desde una milla antes de la primera señal hasta una milla después de la última"], explanation_es: "La zona de obras es el área entre la primera señal que indica el inicio de la zona y la última señal que indica su final." },
  { id: "signs-26", topic: "signs", difficulty: "easy", sign: "flagger-ahead", question: "What does this sign warn you about?", choices: ["A worker ahead is using a STOP/SLOW paddle to control traffic, so be ready to stop", "A school crossing guard is ahead", "Pedestrians may cross anywhere in the next mile", "A police checkpoint is ahead"], answerIndex: 0, explanation: "The Flagger sign warns of road work ahead where a flagger in an orange vest uses a STOP/SLOW paddle; stay alert and be prepared to stop.", question_pt: "Sobre o que esta placa alerta?", choices_pt: ["Um trabalhador à frente está usando uma placa PARE/DEVAGAR para controlar o trânsito, então esteja pronto para parar", "Há um guarda de travessia escolar à frente", "Pedestres podem atravessar em qualquer ponto na próxima milha", "Há uma blitz policial à frente"], explanation_pt: "A placa de sinalizador (Flagger) alerta sobre obras à frente, onde um trabalhador de colete laranja usa uma placa PARE/DEVAGAR (STOP/SLOW); fique atento e preparado para parar.", question_es: "¿Sobre qué le advierte esta señal?", choices_es: ["Un trabajador más adelante usa una paleta de ALTO/DESPACIO para controlar el tránsito, así que prepárese para detenerse", "Hay un guardia de cruce escolar más adelante", "Los peatones pueden cruzar en cualquier punto en la próxima milla", "Hay un retén policial más adelante"], explanation_es: "La señal de abanderado advierte de obras más adelante, donde un abanderado con chaleco naranja usa una paleta STOP/SLOW; manténgase alerta y prepárese para detenerse." },
  { id: "signs-27", topic: "signs", difficulty: "easy", sign: "handicap-parking", question: "Who may park in a space marked with this sign?", choices: ["Any driver, for up to 15 minutes", "Drivers of delivery vehicles", "Anyone driving with an elderly passenger", "A qualifying person displaying a handicap license plate or dashboard placard"], answerIndex: 3, explanation: "The handicap parking sign reserves the space for people who qualify for and display a handicap license plate or a dashboard placard.", question_pt: "Quem pode estacionar em uma vaga marcada com esta placa?", choices_pt: ["Qualquer motorista, por até 15 minutos", "Motoristas de veículos de entrega", "Qualquer pessoa dirigindo com um passageiro idoso", "Uma pessoa qualificada que exiba placa de veículo ou cartão de painel para deficientes"], explanation_pt: "A placa de estacionamento para deficientes reserva a vaga para pessoas que se qualificam e exibem uma placa de veículo ou um cartão de painel para deficientes.", question_es: "¿Quién puede estacionarse en un espacio marcado con esta señal?", choices_es: ["Cualquier conductor, hasta por 15 minutos", "Conductores de vehículos de reparto", "Cualquier persona que conduzca con un pasajero de edad avanzada", "Una persona que califique y muestre una placa o un cartel en el tablero para discapacitados"], explanation_es: "La señal de estacionamiento para discapacitados reserva el espacio para personas que califican y muestran una placa para discapacitados o un cartel en el tablero." },
  { id: "signs-28", topic: "signs", difficulty: "hard", sign: "nc-route", question: "Which statement about this route marker is correct?", choices: ["It marks a U.S. highway that generally runs north and south", "It marks an N.C. state highway that generally runs east and west", "It marks an interstate highway that generally runs east and west", "It marks an N.C. secondary road that generally runs north and south"], answerIndex: 1, explanation: "N.C. route markers are diamond-shaped, and route 54 has an even number, so it generally runs east and west.", question_pt: "Qual afirmação sobre este marcador de rota está correta?", choices_pt: ["Indica uma rodovia federal (U.S.) que geralmente segue de norte a sul", "Indica uma rodovia estadual da Carolina do Norte (N.C.) que geralmente segue de leste a oeste", "Indica uma rodovia interestadual que geralmente segue de leste a oeste", "Indica uma estrada secundária da Carolina do Norte que geralmente segue de norte a sul"], explanation_pt: "Os marcadores das rotas N.C. têm forma de losango, e a rota 54 tem número par, então geralmente segue de leste a oeste.", question_es: "¿Qué afirmación sobre este marcador de ruta es correcta?", choices_es: ["Indica una vía nacional (U.S.) que generalmente va de norte a sur", "Indica una vía estatal de Carolina del Norte (N.C.) que generalmente va de este a oeste", "Indica una vía interestatal que generalmente va de este a oeste", "Indica una vía secundaria de Carolina del Norte que generalmente va de norte a sur"], explanation_es: "Las señales de ruta N.C. tienen forma de diamante, y la ruta 54 tiene número par, así que generalmente va de este a oeste." },
  { id: "signs-29", topic: "signs", difficulty: "medium", sign: "us-route", question: "You are lost and want to study this route marker and a nearby mileage sign. What should you do?", choices: ["When safe, move to the shoulder and wait there until you figure out your route", "Stop briefly in your lane with your flashers on", "Slow to 10 mph in the travel lane while you read", "Back up to get a better look at the signs"], answerIndex: 0, explanation: "Do not endanger other drivers by stopping in the road to read a sign; when it is safe, move to the shoulder and wait until you know where you are and which route to take.", question_pt: "Você está perdido e quer analisar este marcador de rota e uma placa de distâncias próxima. O que deve fazer?", choices_pt: ["Quando for seguro, ir para o acostamento e esperar ali até descobrir seu caminho", "Parar rapidamente na sua faixa com o pisca-alerta ligado", "Reduzir para 10 mph na faixa de rodagem enquanto lê", "Dar ré para ver as placas melhor"], explanation_pt: "Não coloque outros motoristas em perigo parando na pista para ler uma placa; quando for seguro, vá para o acostamento e espere até saber onde está e qual rota seguir.", question_es: "Está perdido y quiere estudiar este marcador de ruta y una señal de millaje cercana. ¿Qué debe hacer?", choices_es: ["Cuando sea seguro, moverse al arcén y esperar allí hasta decidir su ruta", "Detenerse un momento en su carril con las luces intermitentes encendidas", "Reducir a 10 mph en el carril mientras lee", "Retroceder para ver mejor las señales"], explanation_es: "No ponga en peligro a otros conductores deteniéndose en medio de la vía para leer una señal; cuando sea seguro, muévase al arcén y espere hasta saber dónde está y qué ruta seguir." },
  { id: "signs-30", topic: "signs", difficulty: "hard", sign: "do-not-enter", question: "You missed this sign and realize you have entered an interstate going the wrong direction. What should you do?", choices: ["Make a U-turn across the median right away", "Keep driving the wrong way to the next exit", "Pull over to the right shoulder and stop, then turn around when the way is clear", "Back up along the ramp to where you entered"], answerIndex: 2, explanation: "If you enter an interstate headed the wrong way, pull over to the right shoulder and stop; when the way is clear, turn around and head in the proper direction. Watching for DO NOT ENTER signs helps you avoid this error.", question_pt: "Você não viu esta placa e percebe que entrou em uma rodovia interestadual na contramão. O que deve fazer?", choices_pt: ["Fazer um retorno imediatamente pelo canteiro central", "Continuar na contramão até a próxima saída", "Ir para o acostamento da direita e parar, depois dar a volta quando o caminho estiver livre", "Dar ré pela rampa até onde você entrou"], explanation_pt: "Se entrar em uma interestadual na direção errada, vá para o acostamento da direita e pare; quando o caminho estiver livre, dê a volta e siga na direção correta. Ficar atento às placas PROIBIDO ENTRAR (DO NOT ENTER) evita esse erro.", question_es: "No vio esta señal y se da cuenta de que entró a una vía interestatal en sentido contrario. ¿Qué debe hacer?", choices_es: ["Dar una vuelta en U de inmediato por la mediana", "Seguir en sentido contrario hasta la próxima salida", "Orillarse al arcén derecho y detenerse, y luego dar la vuelta cuando el camino esté despejado", "Retroceder por la rampa hasta donde entró"], explanation_es: "Si entra a una interestatal en sentido contrario, oríllese al arcén derecho y deténgase; cuando el camino esté despejado, dé la vuelta y siga en la dirección correcta. Fijarse en las señales NO ENTRE [DO NOT ENTER] ayuda a evitar este error." },
  { id: "signs-31", topic: "signs", difficulty: "hard", sign: "railroad-advance", question: "After passing this sign, you reach the crossing and its signal is warning of an approaching train. Where must you stop under North Carolina law?", choices: ["Directly on the first rail so you can see down the track", "At least 100 feet from the nearest rail", "Within 10 feet of the nearest rail", "Within 50 feet, but no closer than 15 feet, from the nearest rail"], answerIndex: 3, explanation: "NC law (G.S. 20-142.1) requires you to stop within 50 feet, but not less than 15 feet, from the nearest rail and not proceed until it is safe.", question_pt: "Depois de passar por esta placa, você chega à passagem de nível e o sinal está avisando que um trem se aproxima. Onde você deve parar pela lei da Carolina do Norte?", choices_pt: ["Em cima do primeiro trilho, para enxergar a linha", "A pelo menos 100 pés do trilho mais próximo", "A até 10 pés do trilho mais próximo", "A no máximo 50 pés, mas não a menos de 15 pés, do trilho mais próximo"], explanation_pt: "A lei da Carolina do Norte (G.S. 20-142.1) exige parar a no máximo 50 pés, mas não a menos de 15 pés, do trilho mais próximo, e só seguir quando for seguro.", question_es: "Después de pasar esta señal, llega al cruce y su señal advierte que se acerca un tren. Según la ley de Carolina del Norte, ¿dónde debe detenerse?", choices_es: ["Justo sobre el primer riel para ver la vía", "Al menos a 100 pies del riel más cercano", "A no más de 10 pies del riel más cercano", "A no más de 50 pies, pero no a menos de 15 pies, del riel más cercano"], explanation_es: "La ley de Carolina del Norte (G.S. 20-142.1) exige detenerse a no más de 50 pies, pero no a menos de 15 pies, del riel más cercano, y no avanzar hasta que sea seguro." },
  { id: "signs-32", topic: "signs", difficulty: "medium", sign: "merge", question: "What does this yellow warning sign tell you?", choices: ["Your lane ends and you must take the next exit", "Traffic from another lane or road will be joining your roadway ahead, so watch for vehicles entering", "A two-way left-turn lane begins ahead", "The divided highway ends ahead"], answerIndex: 1, explanation: "This diamond-shaped warning sign shows another stream of traffic merging into yours ahead; be ready to adjust your speed and space so vehicles can merge safely.", question_pt: "O que esta placa amarela de advertência indica?", choices_pt: ["Sua faixa termina e você deve pegar a próxima saída", "O tráfego de outra faixa ou via vai se juntar à sua pista mais à frente, então fique atento aos veículos entrando", "Uma faixa central de conversão à esquerda nos dois sentidos começa à frente", "A rodovia com canteiro central termina à frente"], explanation_pt: "Esta placa de advertência em forma de losango mostra outro fluxo de tráfego se juntando ao seu mais à frente; esteja pronto para ajustar a velocidade e o espaço para que os veículos entrem com segurança.", question_es: "¿Qué le indica esta señal amarilla de advertencia?", choices_es: ["Su carril termina y debe tomar la próxima salida", "El tránsito de otro carril o vía se unirá a su camino más adelante, así que esté atento a los vehículos que entran", "Más adelante comienza un carril central de giro a la izquierda en ambos sentidos", "La vía dividida termina más adelante"], explanation_es: "Esta señal de advertencia tipo diamante muestra otra corriente de tránsito incorporándose a la suya más adelante; prepárese para ajustar su velocidad y espacio para que los vehículos se incorporen de manera segura." },
  { id: "signs-33", topic: "signs", difficulty: "medium", sign: "lane-ends", question: "You are driving in the lane that this sign shows ending. What should you do?", choices: ["Signal and move into the remaining lane when it is safe, before your lane ends", "Speed up to pass the cars in the other lane before your lane ends", "Stop at the end of your lane and wait for a long gap", "Nothing; the sign applies only to trucks"], answerIndex: 0, explanation: "This yellow warning sign tells you a lane ends ahead; act early and merge safely into the remaining lane, matching the flow of traffic.", question_pt: "Você está na faixa que esta placa mostra terminando. O que deve fazer?", choices_pt: ["Sinalizar e passar para a faixa que continua quando for seguro, antes que a sua termine", "Acelerar para ultrapassar os carros da outra faixa antes que a sua termine", "Parar no fim da sua faixa e esperar um intervalo grande", "Nada; a placa vale só para caminhões"], explanation_pt: "Esta placa amarela de advertência indica que uma faixa termina à frente; aja com antecedência e entre com segurança na faixa que continua, acompanhando o fluxo do tráfego.", question_es: "Usted va en el carril que esta señal muestra que termina. ¿Qué debe hacer?", choices_es: ["Señalizar y pasarse al carril que continúa cuando sea seguro, antes de que termine el suyo", "Acelerar para rebasar a los autos del otro carril antes de que termine el suyo", "Detenerse al final de su carril y esperar un espacio amplio", "Nada; la señal se aplica solo a camiones"], explanation_es: "Esta señal amarilla de advertencia indica que un carril termina más adelante; actúe con anticipación e incorpórese de manera segura al carril que continúa, siguiendo el flujo del tránsito." },
  { id: "signs-34", topic: "signs", difficulty: "medium", question: "A stop sign requires you to stop, but there is no stop line or marked crosswalk. Where must you stop in North Carolina?", choices: ["Right beside the stop sign, wherever it is posted", "In the middle of the intersection, where you can see best", "Before entering the intersection, at a point where you can see the intersecting street", "50 feet before the stop sign"], answerIndex: 2, explanation: "When there is no stop line or marked crosswalk, NC requires you to stop before entering the intersection, at a point where you have a view of the intersecting street.", question_pt: "Uma placa de PARE exige que você pare, mas não há linha de parada nem faixa de pedestres marcada. Onde você deve parar na Carolina do Norte?", choices_pt: ["Bem ao lado da placa de PARE, onde quer que ela esteja", "No meio do cruzamento, onde se vê melhor", "Antes de entrar no cruzamento, em um ponto de onde você veja a via transversal", "50 pés antes da placa de PARE"], explanation_pt: "Quando não há linha de parada nem faixa de pedestres marcada, a Carolina do Norte exige que você pare antes de entrar no cruzamento, em um ponto de onde veja a via transversal.", question_es: "Una señal de alto le exige detenerse, pero no hay línea de alto ni cruce de peatones marcado. ¿Dónde debe detenerse en Carolina del Norte?", choices_es: ["Justo al lado de la señal de alto, dondequiera que esté", "En medio de la intersección, donde se ve mejor", "Antes de entrar a la intersección, en un punto donde pueda ver la calle que cruza", "50 pies antes de la señal de alto"], explanation_es: "Cuando no hay línea de alto ni cruce de peatones marcado, Carolina del Norte exige detenerse antes de entrar a la intersección, en un punto donde pueda ver la calle que cruza." },
  { id: "signs-35", topic: "signs", difficulty: "hard", question: "According to the NC Driver Handbook, how far from the intersection is a stop sign usually posted?", choices: ["Exactly at the edge of the intersection", "100 to 200 feet before it", "At least 500 feet before it", "Six to 50 feet from it"], answerIndex: 3, explanation: "The NC Driver Handbook states that the stop sign is usually posted six to 50 feet from the intersection.", question_pt: "Segundo o manual do motorista da Carolina do Norte, a que distância do cruzamento a placa de PARE geralmente fica?", choices_pt: ["Exatamente na borda do cruzamento", "De 100 a 200 pés antes dele", "Pelo menos 500 pés antes dele", "De seis a 50 pés dele"], explanation_pt: "O manual do motorista da Carolina do Norte diz que a placa de PARE geralmente fica de seis a 50 pés do cruzamento.", question_es: "Según el manual del conductor de Carolina del Norte, ¿a qué distancia de la intersección se coloca generalmente la señal de alto?", choices_es: ["Exactamente en el borde de la intersección", "De 100 a 200 pies antes de ella", "Al menos 500 pies antes de ella", "Entre seis y 50 pies de ella"], explanation_es: "El manual del conductor de Carolina del Norte indica que la señal de alto generalmente se encuentra entre seis y 50 pies de la intersección." },
  { id: "signs-36", topic: "signs", difficulty: "easy", question: "Interstate, U.S. and N.C. highways with odd numbers generally run in which direction?", choices: ["East and west", "North and south", "In a loop around a city", "Toward the coast"], answerIndex: 1, explanation: "Odd-numbered highways generally run north and south, while even-numbered highways generally run east and west.", question_pt: "Rodovias interestaduais, federais (U.S.) e estaduais (N.C.) com números ímpares geralmente seguem em que direção?", choices_pt: ["Leste–oeste", "Norte–sul", "Em anel ao redor de uma cidade", "Em direção ao litoral"], explanation_pt: "Rodovias com número ímpar geralmente seguem de norte a sul, enquanto as de número par geralmente seguem de leste a oeste.", question_es: "¿En qué dirección van generalmente las vías interestatales, nacionales (U.S.) y estatales (N.C.) con números impares?", choices_es: ["De este a oeste", "De norte a sur", "En un anillo alrededor de una ciudad", "Hacia la costa"], explanation_es: "Las vías con números impares generalmente van de norte a sur, mientras que las de números pares generalmente van de este a oeste." }
]);
